'use client';

// Vendored from MerchFlow Charts components/web/ShowsChart.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { useState } from 'react';
import { chartInk, gms, webText } from '@/lib/merch-flow-report/brand/tokens';
import { niceMax, shortDate } from '@/lib/merch-flow-report/format';
import type { Show } from '@/lib/merch-flow-report/report/types';
import { useContainerWidth } from './useContainerWidth';

/**
 * Responsive column chart with a hover layer.
 *
 * Single series, so one hue and no legend — the heading names the measure.
 * On narrow viewports the city labels are dropped rather than overlapped; the
 * tooltip carries the identity instead.
 */
export function ShowsChart({
  shows,
  measure,
  format,
  formatAxis,
  averageLabel,
}: {
  shows: Show[];
  measure: (s: Show) => number;
  format: (n: number) => string;
  formatAxis: (n: number) => string;
  averageLabel: string;
}) {
  const { ref, width } = useContainerWidth();
  const [hover, setHover] = useState<number | null>(null);

  const showLabels = width >= 900;
  // Rotated labels extend downward from the axis, so the gutter has to fit the
  // longest city name or it silently clips the start of the word.
  const longestCity = shows.reduce((n, s) => Math.max(n, s.city.trim().length), 0);
  const labelGutter = showLabels ? Math.ceil(longestCity * 5.4) + 18 : 26;
  const plotHeight = width < 640 ? 220 : 320;
  const height = plotHeight + labelGutter;

  const pad = {
    top: 14,
    right: 10,
    bottom: labelGutter,
    left: width < 480 ? 46 : 60,
  };

  const plotW = Math.max(width - pad.left - pad.right, 10);
  const plotH = height - pad.top - pad.bottom;
  const max = niceMax(Math.max(...shows.map(measure), 0));
  const average = shows.length ? shows.reduce((s, x) => s + measure(x), 0) / shows.length : 0;

  const slot = plotW / Math.max(shows.length, 1);
  const barW = Math.max(Math.min(slot - 2, 18), 1.5);
  const y = (v: number) => pad.top + plotH - (v / max) * plotH;
  const ticks = Array.from({ length: 5 }, (_, i) => (max / 4) * i);

  const active = hover !== null ? shows[hover] : null;

  return (
    <div ref={ref} className="relative w-full">
      {width > 0 && (
        <svg width={width} height={height} className="block">
          {ticks.map((t) => (
            <g key={t}>
              <line
                x1={pad.left}
                x2={pad.left + plotW}
                y1={y(t)}
                y2={y(t)}
                stroke={chartInk.grid}
              />
              <text
                x={pad.left - 8}
                y={y(t) + 4}
                textAnchor="end"
                fontSize={10}
                fill={webText.secondary}
                className="tnum"
              >
                {formatAxis(t)}
              </text>
            </g>
          ))}

          {average > 0 && (
            <line
              x1={pad.left}
              x2={pad.left + plotW}
              y1={y(average)}
              y2={y(average)}
              stroke={gms.black}
              strokeWidth={1.5}
              strokeDasharray="5 4"
            />
          )}

          {shows.map((s, i) => {
            const v = measure(s);
            const h = Math.max((v / max) * plotH, v > 0 ? 1.5 : 0);
            const x = pad.left + i * slot + (slot - barW) / 2;
            return (
              <g key={`${s.date}-${s.city}`}>
                <rect
                  x={x}
                  y={pad.top + plotH - h}
                  width={barW}
                  height={h}
                  rx={Math.min(4, barW / 2)}
                  fill={hover === i ? gms.black : gms.red}
                />
                {/* Hit target wider than the mark, so touch works. */}
                <rect
                  x={pad.left + i * slot}
                  y={pad.top}
                  width={Math.max(slot, 10)}
                  height={plotH}
                  fill="transparent"
                  onMouseEnter={() => setHover(i)}
                  onMouseLeave={() => setHover(null)}
                  onTouchStart={() => setHover(i)}
                />
              </g>
            );
          })}

          {showLabels &&
            shows.map((s, i) => {
              const x = pad.left + i * slot + slot / 2;
              return (
                <text
                  key={`${s.date}-label`}
                  x={x}
                  y={pad.top + plotH + 8}
                  fontSize={9}
                  fill={hover === i ? gms.black : webText.secondary}
                  textAnchor="end"
                  transform={`rotate(-90 ${x} ${pad.top + plotH + 8})`}
                >
                  {s.city}
                </text>
              );
            })}

          <line
            x1={pad.left}
            x2={pad.left + plotW}
            y1={pad.top + plotH}
            y2={pad.top + plotH}
            stroke={chartInk.axis}
          />
        </svg>
      )}

      <div
        className="pointer-events-none absolute left-0 top-0 rounded px-3 py-2 text-[12px] text-white transition-opacity"
        style={{
          background: gms.black,
          opacity: active ? 1 : 0,
          transform: `translate(${Math.min(
            Math.max((hover ?? 0) * (plotW / Math.max(shows.length, 1)) + pad.left - 60, 0),
            Math.max(width - 170, 0),
          )}px, -6px)`,
        }}
      >
        {active && (
          <>
            <div className="font-semibold">{active.city}</div>
            <div style={{ color: gms.mist }}>{shortDate(active.date)}</div>
            <div className="tnum mt-0.5 font-bold">{format(measure(active))}</div>
          </>
        )}
      </div>

      <p className="mt-2 text-[12px]" style={{ color: webText.secondary }}>
        Dashed line — {averageLabel} {format(average)}
      </p>
    </div>
  );
}
